import os, json, time
import numpy as np

N = 26
SHARED_DIR = 'storage/shared/appxE_contribs'
TARGET_FILE = os.path.join(SHARED_DIR, 'quest_II_eval820_appxE_v3.1.json')
OUT_DIR = 'storage/noesis/nmap/results'
NOESIS_C = 'storage/noesis/latest_centers.txt'
NOESIS_R = 'storage/noesis/latest_radii.txt'
AUDIT_SLACK = 'storage/noesis/nmap/results/noesis_internal_topk_audit.json'
AUDIT_KKT   = 'storage/noesis/nmap/results/noesis_internal_kkt_topk_audit.json'

K_GRID = [15, 25, 40, 60]
TOLS = [1e-9, 1e-8]
BOUNDARY_TOL = 2e-8

def load_snapshot():
    if os.path.exists(NOESIS_C) and os.path.exists(NOESIS_R):
        c = np.loadtxt(NOESIS_C, dtype=float).reshape(N, 2)
        r = np.loadtxt(NOESIS_R, dtype=float).reshape(N,)
        return c, r
    # Fallback: feasible grid+hole (conservative)
    centers = []
    radius = 0.08
    for i in range(5):
        for j in range(6):
            if len(centers) < 26:
                x = 0.1 + i * 0.2
                y = 0.1 + j * 0.15
                centers.append([x, y])
    return np.array(centers, float), np.full(N, radius, float)

def slacks(c, r):
    x = c[:,0]; y = c[:,1]
    s_xL = x - r
    s_xR = 1.0 - x - r
    s_yB = y - r
    s_yT = 1.0 - y - r
    return s_xL, s_xR, s_yB, s_yT

def boundary_set(c, r, tol):
    s_xL, s_xR, s_yB, s_yT = slacks(c, r)
    out = set()
    for i in range(N):
        if s_xL[i] <= tol: out.add((i, 'xL'))
        if s_xR[i] <= tol: out.add((i, 'xR'))
        if s_yB[i] <= tol: out.add((i, 'yB'))
        if s_yT[i] <= tol: out.add((i, 'yT'))
    return out

def jaccard(A, B):
    if not A and not B: return 1.0
    if not A or not B: return 0.0
    inter = len(A & B); uni = len(A | B)
    return inter/uni if uni > 0 else 1.0

def load_json(path):
    with open(path, 'r') as f:
        return json.load(f)

def norm_tol(t):
    if isinstance(t, (int, float)): return float(t)
    if isinstance(t, str):
        t = t.replace('−','-').strip()
        try: return float(t)
        except: pass
    return None

def get_index_map(data):
    # schema v1.1: 26-int list mapping contributor index -> noesis index
    im = data.get('index_map_to_noesis')
    if isinstance(im, list) and len(im) == 26 and all(isinstance(x, int) for x in im):
        return im
    return None

def remap_pair(p, idx_map):
    if idx_map is None: return (int(p[0]), int(p[1]))
    i = idx_map[int(p[0])]
    j = idx_map[int(p[1])]
    return (int(i), int(j))

def remap_boundary_entry(e, idx_map):
    disc = int(e['disc'])
    side = str(e['side'])
    if idx_map is not None:
        disc = idx_map[disc]
    return (disc, side)

def load_contrib_boundary(data, idx_map):
    b = data.get('boundary', [])
    out = set()
    for e in b:
        try:
            out.add(remap_boundary_entry(e, idx_map))
        except Exception:
            continue
    return out

def load_contrib_topk(data, method_key):
    # Accept consolidated 'topk': [{method, tol, K, pairs}] or separate keys like 'slack_top_k_1e_9'
    entries = []
    if 'topk' in data and isinstance(data['topk'], list):
        for ent in data['topk']:
            m = ent.get('method')
            if (method_key == 'slack' and str(m).lower().startswith('slack')) or \
               (method_key == 'kkt' and str(m).lower().startswith('kkt')):
                entries.append(ent)
    else:
        # separate keys pattern for slack only
        for key in list(data.keys()):
            if method_key == 'slack' and key.startswith('slack_top_k_'):
                tol_str = key.replace('slack_top_k_','').replace('_','.')
                entries.append({'method':'slack', 'tol': tol_str, 'K': len(data[key]), 'pairs': data[key]})
    return entries

def pairs_to_set(pairs, idx_map):
    S = set()
    for p in pairs:
        try:
            i, j = remap_pair(p, idx_map)
            if i == j: continue
            if i > j: i, j = j, i
            S.add((i, j))
        except Exception:
            continue
    return S

def main():
    c0, r0 = load_snapshot()
    results = {
        'source_file': os.path.basename(TARGET_FILE),
        'generated_at': time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime()),
        'notes': [],
        'boundary': {},
        'topk_slack': {},
        'topk_kkt': {},
    }

    if not os.path.exists(TARGET_FILE):
        results['notes'].append('target_file_missing')
        os.makedirs(OUT_DIR, exist_ok=True)
        with open(os.path.join(OUT_DIR, 'quest_II_eval820_appxE_v3_1_compare_v2_1.json'), 'w') as f:
            json.dump(results, f, indent=2)
        # Return baseline
        r = np.maximum(r0 - 1e-9, 1e-12)
        return c0.astype(float), r.astype(float)

    data = load_json(TARGET_FILE)
    idx_map = get_index_map(data)

    # Boundary Jaccard @ 2e-8
    B_noe = boundary_set(c0, r0, tol=BOUNDARY_TOL)
    B_contrib = load_contrib_boundary(data, idx_map)
    results['boundary'] = {
        'tol': BOUNDARY_TOL,
        'noesis_count': len(B_noe),
        'contrib_count': len(B_contrib),
        'jaccard': jaccard(B_noe, B_contrib)
    }

    # Load Noesis audits
    slack_audit = load_json(AUDIT_SLACK) if os.path.exists(AUDIT_SLACK) else None
    kkt_audit   = load_json(AUDIT_KKT)   if os.path.exists(AUDIT_KKT)   else None

    # Slack overlaps
    results['topk_slack'] = {'entries': []}
    slack_entries = load_contrib_topk(data, 'slack')
    # Normalize contrib entries by tol and K and compute overlaps against Noesis slack audit
    for ent in slack_entries:
        t = norm_tol(ent.get('tol'))
        K = int(ent.get('K', len(ent.get('pairs', []))))
        if t not in TOLS or K not in K_GRID: 
            continue
        S_contrib = pairs_to_set(ent.get('pairs', []), idx_map)
        S_noe = set()
        try:
            noe_list = slack_audit['topk_pairs'][str(t)][str(K)]
            S_noe = pairs_to_set(noe_list, None)  # already in Noesis index
        except Exception:
            pass
        results['topk_slack']['entries'].append({
            'tol': t, 'K': K,
            'contrib_size': len(S_contrib),
            'noesis_size': len(S_noe),
            'jaccard': jaccard(S_noe, S_contrib)
        })

    # KKT overlaps (optional)
    results['topk_kkt'] = {'entries': []}
    kkt_entries = load_contrib_topk(data, 'kkt')
    for ent in kkt_entries:
        t = norm_tol(ent.get('tol'))
        K = int(ent.get('K', len(ent.get('pairs', []))))
        if t not in TOLS or K not in K_GRID:
            continue
        S_contrib = pairs_to_set(ent.get('pairs', []), idx_map)
        S_noe = set()
        try:
            noe_list = kkt_audit['topk_pairs'][str(t)][str(K)]
            S_noe = pairs_to_set(noe_list, None)
        except Exception:
            pass
        results['topk_kkt']['entries'].append({
            'tol': t, 'K': K,
            'contrib_size': len(S_contrib),
            'noesis_size': len(S_noe),
            'jaccard': jaccard(S_noe, S_contrib)
        })

    os.makedirs(OUT_DIR, exist_ok=True)
    out_path = os.path.join(OUT_DIR, 'quest_II_eval820_appxE_v3_1_compare_v2_1.json')
    with open(out_path, 'w') as f:
        json.dump(results, f, indent=2)

    # Return baseline with tiny shrink
    r = np.maximum(r0 - 1e-9, 1e-12)
    return c0.astype(float), r.astype(float)

def construct_packing():
    return main()
